contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        // record total observable funds before interacting: contract c balance + this contract balance
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // perform deposit to c
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // attempt withdrawAll and detect revert
        bool withdrew;
        uint afterC_postAttempt;
        uint afterThis_postAttempt;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrew = false;
        } else {
            withdrew = true;
        }

        afterC_postAttempt = address(c).balance;
        afterThis_postAttempt = address(this).balance;

        // If withdrawAll succeeded then the total observable funds (c + this) should be >= prior total (no loss).
        // If it reverted then no state change is required; allow either outcome.
        assert(!withdrew || (afterC_postAttempt + afterThis_postAttempt >= beforeC + beforeThis));
    }
    receive() external payable { }
}

